code.C:
#include <stdio.h>

int main() {
    long long n;
    if (scanf("%lld", &n) == 1) {
        long long sum = 0;
        for (long long i = 2; i <= n; i += 2) sum += i;
        printf("%lld\n", sum);
    }
    return 0;
}

